def factorial(n: int) -> int:
    """ Return the factorial of n. For n = 0 or 1, the factorial is 1.
    >>> factorial(0)
    1
    >>> factorial(5)
    120
    """
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

def number_of_ways_to_sum(numbers: List[int], target_sum: int) -> int:
    """ Return the number of ways to sum elements of a list to achieve a target sum.
    >>> number_of_ways_to_sum([], 5)
    0
    >>> number_of_ways_to_sum([1, 2, 3, 4], 5)
    2
    """
    if not numbers:
        return 0
    dp = [0] * (target_sum + 1)
    dp[0] = 1
    for number in numbers:
        for i in range(target_sum, number - 1, -1):
            dp[i] += dp[i - number]
    return dp[target_sum]

def find_max_subarray(numbers: List[int]) -> Tuple[int, int, int]:
    """ Return the maximum subarray of a list and its sum.
    >>> find_max_subarray([1, -2, 3, -4, 5])
    (3, 9)
    """
    if not numbers:
        return 0, 0, 0
    max_sum = current_sum = numbers[0]
    start = end = 0
    for i in range(1, len(numbers)):
        current_sum = max(numbers[i], current_sum + numbers[i])
        if current_sum > max_sum:
            max_sum = current_sum
            start = end = i
        elif current_sum == max_sum:
            end = i
    return max_sum, start, end

