from typing import *
from collections import *

class Solution:
    def longestPalindrome(self, s: str) -> str:
        """ Find the longest palindromic substring of a given string. """
        if len(s) <= 1:
            return s
        if s == s[::-1]:
            return s
        mid = len(s) // 2
        l1 = self.longestPalindrome(s[:mid])
        l2 = self.longestPalindrome(s[mid+1:])
        if len(l1) > len(l2):
            return l1 + s[mid]
        else:
            return l2 + s[:mid]

    def longestPalindromeDynamicProgramming(self, s: str) -> str:
        """ Use dynamic programming to solve the problem. """
        n = len(s)
        if n <= 1:
            return s
        # dp[i][j] is true if s[i:j+1] is a palindrome
        dp = [[False] * n for _ in range(n)]
        # Every single character is a palindrome
        for i in range(n):
            dp[i][i] = True
        # Check for palindromes of length 2
        for i in range(n-1):
            if s[i] == s[i+1]:
                dp[i][i+1] = True
        # Check for palindromes of length 3 or more
        for length in range(3, n+1):
            for start in range(n-length+1):
                end = start + length - 1
                if s[start] == s[end] and dp[start+1][end-1]:
                    dp[start][end] = True
        # The longest palindromic substring is the one that is true in dp
        start = end = 0
        for i in range(n):
            for j in range(i, n):
                if dp[i][j] and (end - start + 1 < j - i + 1):
                    start, end = i, j
        return s[start:end+1]

