function hasNestedBracketSequence(str) {
    // Initialize counters for opening and closing brackets
    let openBrackets = 0;
    let closeBrackets = 0;

    // Iterate through each character in the string
    for (let char of str) {
        // Increment count if the character is an opening bracket
        if (char === '[') {
            openBrackets++;
        }
        // Decrement count if the character is a closing bracket
        else if (char === ']') {
            closeBrackets++;
        }

        // Check if the closing bracket count exceeds the opening bracket count
        if (closeBrackets > openBrackets) {
            return true; // Nested sequence found
        }
    }

    // Return false if no nested sequence is found
    return false;
}

