/**
 * You are given a positive integer n. You have to create an integer array a of length n.
 *     For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
 *     Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
 *     and a[i] + a[j] + a[k] is a multiple of 3.
 * 
 * Example :
 *     Input: n = 5
 *     Output: 1
 *     Explanation: 
 *     a = [1, 3, 7, 13, 21]
 *     The only valid triple is (1, 7, 13).
 * */
function getMaxTriples(n) {
    /**
     * @param {number} n
     * @returns {number}
     */
    // Create an array of size n with the given formula
    let a = Array.from({ length: n }, (_, i) => i * i - i + 1);

    // Initialize counters for remainders when divided by 3
    let count0 = 0;
    let count1 = 0;
    let count2 = 0;

    // Count the occurrences of each remainder
    a.forEach(num => {
        if (num % 3 === 0) {
            count0++;
        } else if (num % 3 === 1) {
            count1++;
        } else {
            count2++;
        }
    });

    // Calculate the number of valid triples
    let tripleCount = 0;
    tripleCount += count0 * (count0 - 1) * (count0 - 2) / 6;
    tripleCount += count1 * (count1 - 1) * (count1 - 2) / 6;
    tripleCount += count2 * (count2 - 1) * (count2 - 2) / 6;
    tripleCount += count0 * count1 * count2;
    tripleCount += count1 * count2 * (count1 - 1) / 2;
    tripleCount += count2 * count0 * (count2 - 1) / 2;

    return tripleCount;
}
